static void output_done(void*d,struct wl_output*w){(void)w;report(d);}static void integer(void*d,struct wl_output*w,int32_t n){(void)w;((struct output*)d)->scale=n;}static void name(void*d,struct wl_output*w,const char*n){(void)w;snprintf(((struct output*)d)->name,128,"%s",n);}static void description(void*d,struct wl_output*w,const char*n){(void)d;(void)w;(void)n;}
