static void logical_pos(void*d,struct zxdg_output_v1*x,int32_t a,int32_t b){(void)x;((struct output*)d)->x=a;((struct output*)d)->y=b;}static void logical_size(void*d,struct zxdg_output_v1*x,int32_t a,int32_t b){(void)x;((struct output*)d)->w=a;((struct output*)d)->h=b;}static void xdone(void*d,struct zxdg_output_v1*x){(void)x;report(d);}static void xname(void*d,struct zxdg_output_v1*x,const char*n){(void)x;snprintf(((struct output*)d)->name,128,"%s",n);}static void xdescription(void*d,struct zxdg_output_v1*x,const char*n){(void)d;(void)x;(void)n;}static const struct zxdg_output_v1_listener xl={logical_pos,logical_size,xdone,xname,xdescription};
static void services(void){if(om)for(int i=0;i<count;i++)if(outputs[i].alive&&!outputs[i].xdg){outputs[i].xdg=zxdg_output_manager_v1_get_xdg_output(om,outputs[i].wl);zxdg_output_v1_add_listener(outputs[i].xdg,&xl,&outputs[i]);}}
