static void paint(void){if(!painted)return;int pw=(width*scale+60)/120,ph=(height*scale+60)/120,bytes=pw*ph*4;int fd=memfd_create("hidpi",MFD_CLOEXEC);assert(fd>=0&&ftruncate(fd,bytes)==0);unsigned*p=mmap(NULL,bytes,PROT_READ|PROT_WRITE,MAP_SHARED,fd,0);assert(p!=MAP_FAILED);for(int y=0;y<ph;y++)for(int x=0;x<pw;x++)p[y*pw+x]=(x&1)?0xffc04020:0xff20c040;struct wl_shm_pool*pool=wl_shm_create_pool(shm,fd,bytes);struct wl_buffer*b=wl_shm_pool_create_buffer(pool,0,pw,ph,pw*4,WL_SHM_FORMAT_XRGB8888);wl_buffer_add_listener(b,&bl,NULL);wl_shm_pool_destroy(pool);munmap(p,bytes);close(fd);wp_viewport_set_destination(viewport,width,height);wl_surface_attach(surface,b,0,0);wl_surface_damage(surface,0,0,width,height);wl_surface_commit(surface);printf("paint logical=%d,%d pixels=%d,%d scale=%d full=%d max=%d\n",width,height,pw,ph,scale,full,maximum);}
static void fractional(void*d,struct wp_fractional_scale_v1*f,uint32_t n){(void)d;(void)f;scale=n;printf("scale %u\n",n);paint();}static const struct wp_fractional_scale_v1_listener fl={fractional};
