static void global(void*d,struct wl_registry*r,uint32_t id,const char*n,uint32_t v){(void)d;if(!strcmp(n,"wl_compositor"))compositor=wl_registry_bind(r,id,&wl_compositor_interface,v<4?v:4);else if(!strcmp(n,"wl_shm"))shm=wl_registry_bind(r,id,&wl_shm_interface,1);else if(!strcmp(n,"xdg_wm_base")){shell=wl_registry_bind(r,id,&xdg_wm_base_interface,v<3?v:3);xdg_wm_base_add_listener(shell,&shl,NULL);}else if(!strcmp(n,"wp_viewporter"))vp=wl_registry_bind(r,id,&wp_viewporter_interface,1);else if(!strcmp(n,"wp_fractional_scale_manager_v1"))fm=wl_registry_bind(r,id,&wp_fractional_scale_manager_v1_interface,1);else if(!strcmp(n,"zxdg_output_manager_v1"))om=wl_registry_bind(r,id,&zxdg_output_manager_v1_interface,v<3?v:3);else if(!strcmp(n,"wl_output")){assert(count<64);struct output*o=&outputs[count++];o->id=id;o->alive=1;o->wl=wl_registry_bind(r,id,&wl_output_interface,v<4?v:4);wl_output_add_listener(o->wl,&ol,o);}else if(!strcmp(n,"wl_seat")){struct wl_seat*s=wl_registry_bind(r,id,&wl_seat_interface,1);wl_seat_add_listener(s,&se,NULL);}services();}
static void removed(void*d,struct wl_registry*r,uint32_t id){(void)d;(void)r;for(int i=0;i<count;i++)if(outputs[i].alive&&outputs[i].id==id){printf("removed %s\n",outputs[i].name);outputs[i].alive=0;if(outputs[i].xdg)zxdg_output_v1_destroy(outputs[i].xdg);if(wl_output_get_version(outputs[i].wl)>=3)wl_output_release(outputs[i].wl);}}static const struct wl_registry_listener rl={global,removed};
int main(void){setbuf(stdout,NULL);display=wl_display_connect(NULL);assert(display);struct wl_registry*r=wl_display_get_registry(display);wl_registry_add_listener(r,&rl,NULL);for(int i=0;i<100&&(!fm||!vp);i++){assert(wl_display_roundtrip(display)>=0);if(!fm||!vp)usleep(10000);}assert(compositor&&shm&&shell&&fm&&vp);assert(wl_display_roundtrip(display)>=0);surface=wl_compositor_create_surface(compositor);wl_surface_add_listener(surface,&sul,NULL);viewport=wp_viewporter_get_viewport(vp,surface);struct wp_fractional_scale_v1*f=wp_fractional_scale_manager_v1_get_fractional_scale(fm,surface);wp_fractional_scale_v1_add_listener(f,&fl,NULL);xdg=xdg_wm_base_get_xdg_surface(shell,surface);xdg_surface_add_listener(xdg,&sl,NULL);top=xdg_surface_get_toplevel(xdg);xdg_toplevel_add_listener(top,&tl,NULL);xdg_toplevel_set_title(top,"Trames HiDPI");xdg_toplevel_set_app_id(top,"org.trames.hidpi");xdg_toplevel_set_min_size(top,160,100);xdg_toplevel_set_max_size(top,640,480);wl_surface_commit(surface);while(!done){while(wl_display_prepare_read(display)!=0)assert(wl_display_dispatch_pending(display)>=0);assert(wl_display_flush(display)>=0);struct pollfd fds[2]={{wl_display_get_fd(display),POLLIN,0},{0,POLLIN,0}};assert(poll(fds,2,30000)>0);if(fds[0].revents&POLLIN)assert(wl_display_read_events(display)>=0);else wl_display_cancel_read(display);assert(wl_display_dispatch_pending(display)>=0);if(fds[1].revents&POLLIN){char c;assert(read(0,&c,1)==1);printf("command %c\n",c);if(c=='q')done=1;else if(c=='f'){struct output*o=NULL;for(int i=0;i<count;i++)if(outputs[i].alive&&strstr(outputs[i].name,"2"))o=&outputs[i];assert(o);xdg_toplevel_set_fullscreen(top,o->wl);}else if(c=='u')xdg_toplevel_unset_fullscreen(top);else if(c=='s'){width=300;height=200;paint();}else if(c=='p')paint();}}
wp_fractional_scale_v1_destroy(f);wp_viewport_destroy(viewport);xdg_toplevel_destroy(top);xdg_surface_destroy(xdg);wl_surface_destroy(surface);wl_display_flush(display);wl_display_disconnect(display);puts("hidpi-done");return 0;}
